def local_scorer(input, output, expected):
    return 1.0 if output == expected.upper() else 0.0

result = Eval(
    'Local Test',
    experiment_name='Local Experiment',
    data=[
        {'input': 'hello', 'expected': 'HELLO'},
        {'input': 'world', 'expected': 'WORLD'},
    ],
    task=local_task,
    scores=[local_scorer],
    no_send_logs=True,
)
print('Result:', result)
